import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createNode as noop } from '@/primitives';
import { createText as noopText } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container (position/rotation/scale applied by adapter)
  const root = new Group();

  // Geometry (unit plane, will be scaled by parent if needed)
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously, but keep function synchronous
  let texture;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    texture = tex;
    material.map = tex;
    material.needsUpdate = true;
  });

  // Interaction state
  const originalY = mesh.position.y;
  let hoverTween = null;

  // Handlers exposed via userData
  root.userData.handlers = {
    hover: (isHover) => {
      if (hoverTween) hoverTween.kill();
      const targetY = isHover ? originalY + 0.15 : originalY;
      hoverTween = gsap.to(mesh.position, {
        y: targetY,
        duration: 0.2,
        ease: 'power3.out',
      });
    },
    click: () => {
      ctx.emit('hub-collection.select', {});
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    geometry.dispose();
    material.dispose();
    if (texture && texture.dispose) texture.dispose();
  };

  return root;
}
